// Раунд 3 (I6): один список форматов у #3, не два разных — иначе PDF/Word
// никогда не покидают «На анализ/» и ветка Фазы 2 (10C) на ночном пути мертва.
// Раунд 3 (I5): .csv распознаётся, но не реализован — уходит в bucket 'unsupported',
// не в 'implemented'.
const IMPLEMENTED = ['.xlsx'];
const LEVEL0_FORMATS = ['.xlsx', '.csv', '.pdf', '.doc', '.docx'];

function ext(name) {
  const m = name.match(/\.[^.]+$/);
  return m ? m[0].toLowerCase() : '';
}

return items.map((item) => {
  const name = item.json.basename || item.json.name || item.json.path;
  const e = ext(name);
  let bucket = 'ignored'; // мусор вроде .DS_Store/Thumbs.db — остаётся в На анализ/ молча
  if (IMPLEMENTED.includes(e)) bucket = 'implemented';
  else if (LEVEL0_FORMATS.includes(e)) bucket = 'unsupported';
  return { json: { ...item.json, filename: name, bucket } };
});
